head.b:skin:
/* Variable Definitions
====================
<Variable name="bg.color" description="خلفية الصفحة" type="color" default="#f3f7fa" value="#f3f7fa"/>
<Variable name="card.bg" description="خلفية البطاقات" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="primary.color" description="اللون الأساسي" type="color" default="#084a72" value="#084a72"/>
<Variable name="primary.dark" description="اللون الأساسي الداكن" type="color" default="#084a72" value="#084a72"/>
<Variable name="accent.color" description="لون التمييز" type="color" default="#12AD2B" value="#12AD2B"/>
<Variable name="text.color" description="لون النص" type="color" default="#1a1a1a" value="#1a1a1a"/>
<Variable name="muted.color" description="لون النص الثانوي" type="color" default="#6b6b6b" value="#6b6b6b"/>
<Variable name="border.color" description="لون الحدود" type="color" default="#dbe4ea" value="#dbe4ea"/>
<Variable name="header.bg" description="خلفية الرأس" type="color" default="#0d6ea8" value="#0d6ea8"/>
<Variable name="footer.bg" description="خلفية التذييل" type="color" default="#084a72" value="#084a72"/>
<Variable name="whatsapp.color" description="لون واتساب" type="color" default="#12AD2B" value="#12AD2B"/>
*/

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: system-ui, -apple-system, 'Segoe UI', Tahoma, Arial, sans-serif;
  background: $(bg.color);
  color: $(text.color);
  line-height: 1.55;
  font-size: clamp(16px, 1.15vw, 18px);
  overflow-x: hidden;
}
a { color: $(primary.color); text-decoration: none; transition: color .2s ease; }
a:hover { color: $(primary.dark); }
img { max-width: 100%; height: auto; display: block; }
ul { list-style: none; }
.visually-hidden { position:absolute !important; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0; }
.skip-link { position:absolute; inset-inline-start:-9999px; top:0; background:$(primary.dark); color:#fff; padding:10px 16px; z-index:9999; border-radius:0 0 8px 0; }
.skip-link:focus { inset-inline-start:0; }
[hidden] { display: none !important; }

/* ===== Unified container (Section 2) ===== */
.container {
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: clamp(14px, 4vw, 32px);
  box-sizing: border-box;
}

/* ===== Blogger Layout Editor isolation (body#layout) ===== */
/* The Blogger layout editor must never inherit the visitor-facing layout rules. */
body#layout {
  display: block !important;
  min-height: 0 !important;
  overflow: visible !important;
  background: #eef1f4 !important;
  color: #1a1a1a !important;
  font-family: Arial, Helvetica, sans-serif !important;
  padding: 0 !important;
}
body#layout #main-wrapper { display: block !important; flex: none !important; }
body#layout .site-header,
body#layout .site-footer,
body#layout .search-bar,
body#layout .nav-toggle,
body#layout .main-nav,
body#layout .skip-link { display: none !important; }
body#layout .container { max-width: 100% !important; padding: 0 10px !important; }
body#layout .main-content { display: block !important; padding: 10px 0 !important; }
body#layout .content-area,
body#layout .sidebar-area,
body#layout .sidebar { display: block !important; width: auto !important; max-width: 100% !important; float: none !important; }
body#layout .property-grid,
body#layout .blog-posts,
body#layout .blog-posts > .section,
body#layout .post,
body#layout .property-card { display: block !important; width: auto !important; max-width: 100% !important; }
body#layout .section { margin: 10px 0 !important; }
body#layout .section h2,
body#layout .section h3 { font-size: 13px !important; }
body#layout .widget { margin: 8px 0 !important; }
body#layout .layout-title,
body#layout .layout-widget-description { display: block !important; }

/* ===== Header ===== */
.site-header {
  background: $(header.bg);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,.12);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 5px 0;
  flex-wrap: nowrap;
  min-height: 60px;
}
.site-logo { color: #fff; display: inline-flex; align-items: center; flex: 0 0 auto; }
.site-logo:hover { color: #fff; opacity: .92; }
.site-logo .logo-icon { width: 84px; height: auto; aspect-ratio: 300 / 165; padding: 0; border-radius: 0; background: transparent; display: flex; align-items: center; justify-content: flex-start; overflow: visible; }
.site-logo .brand-logo { width: 100%; height: auto; max-width: 100%; display: block; object-fit: contain; object-position: center; }
.footer-brand { display: inline-flex; width: min(150px, 100%); max-width: 150px; padding: 0; border-radius: 0; background: transparent; }
.footer-brand .brand-logo { display: block; width: 100%; height: auto; }
.main-nav { display: flex; gap: 2px; flex: 1 1 auto; justify-content: center; flex-wrap: nowrap; min-width: 0; }
.main-nav a { color: rgba(255,255,255,.9); padding: 8px 10px; border-radius: 6px; font-size: clamp(.88rem, 1vw, 1.04rem); font-weight: 600; transition: background .2s ease; white-space: nowrap; }
.main-nav a:hover { background: rgba(255,255,255,.15); color: #fff; }
.nav-toggle { display: none; background: none; border: none; color: #fff; font-size: 1.5rem; cursor: pointer; padding: 4px 8px; }

/* ===== Header widget region ===== */
.header-widgets .widget { color: #fff; }
.header-widgets .widget h2 { display: none; }
.header-widgets, .header-widgets .widget, .header-widgets .widget-content { margin: 0; padding: 0; background: $(primary.dark); line-height: 1; }
.header-promo-bar { width: 100%; min-height: 0; display: flex; align-items: center; justify-content: center; padding: 8px 12px 6px; background: transparent; color: rgba(255,255,255,.97); font-size: clamp(.98rem, 1.35vw, 1.18rem); line-height: 1.35; font-weight: 800; letter-spacing: .01em; }

/* ===== Search Bar ===== */
.search-bar { position: relative; z-index: 2; pointer-events: auto; background: rgba(255,255,255,.1); border-radius: 8px; padding: 6px 9px; display: flex; align-items: center; gap: 6px; flex: 0 1 245px; min-width: 150px; }
.search-bar input[type="text"], .search-bar input[type="search"] { background: transparent; border: none; color: #fff; font-size: clamp(.82rem, .95vw, .95rem); outline: none; width: 100%; min-width: 0; min-height: 34px; font-family: inherit; }
.search-bar input[type="text"]::placeholder, .search-bar input[type="search"]::placeholder { color: rgba(255,255,255,.6); }
.search-bar button { position: relative; z-index: 3; pointer-events: auto; background: $(accent.color); border: none; color: #fff; min-height: 34px; padding: 6px 12px; border-radius: 6px; cursor: pointer; font-size: .84rem; font-weight: 700; font-family: inherit; white-space: nowrap; }

/* ===== Lightweight Hero slider ===== */
.hero { background: $(primary.dark); color: #fff; padding: 0 0 8px; text-align: center; }
.hero > .container { max-width: 1200px; padding-inline: clamp(14px, 4vw, 32px); }

.hero-slider { position: relative; width: 100%; aspect-ratio: 21 / 8; min-height: 190px; max-height: 340px; overflow: hidden; background: $(primary.dark); border-radius: 16px; box-shadow: 0 7px 22px rgba(0,0,0,.18); }
.hero-slides { position: absolute; inset: 0; width: 100%; height: 100%; }
.hero-slide { position: absolute; inset: 0; opacity: 0; visibility: hidden; transition: opacity .32s ease; }
.hero-slide.is-active { opacity: 1; visibility: visible; }
.hero-slide img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hero-slide-shade { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(4,35,57,.18), rgba(4,35,57,.58)); }
.hero-copy { position: absolute; z-index: 2; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 18px 12%; color: #fff; text-align: center; }
.hero-copy h1 { font-size: clamp(1.35rem, 3.2vw, 2.35rem); line-height: 1.25; font-weight: 800; margin-bottom: 8px; text-shadow: 0 2px 7px rgba(0,0,0,.4); }
.hero-copy p { max-width: 650px; font-size: clamp(.8rem, 1.45vw, 1rem); line-height: 1.65; opacity: .97; margin: 0; text-shadow: 0 1px 5px rgba(0,0,0,.4); }
.hero-slider-dots { position: absolute; z-index: 3; inset-inline: 0; bottom: 12px; display: flex; justify-content: center; gap: 8px; }
.hero-slider-dot { width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; background: transparent; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; } .hero-slider-dot::before { content: ''; width: 10px; height: 10px; border: 1px solid #fff; border-radius: 50%; background: transparent; } .hero-slider-dot.is-active::before { background: $(accent.color); border-color: $(accent.color); }

.home-before-posts { margin: 0; }
.home-intro { margin: 22px auto 4px; padding: 22px clamp(16px, 4vw, 42px); background: $(card.bg); border: 1px solid $(border.color); border-radius: 16px; box-shadow: 0 4px 18px rgba(0,0,0,.06); text-align: center; }
.home-intro h1 { color: $(primary.dark); font-size: clamp(1.45rem, 3vw, 2.15rem); line-height: 1.3; font-weight: 800; margin-bottom: 8px; }
.home-intro p { color: $(muted.color); max-width: 760px; margin: 0 auto; font-size: clamp(.96rem, 1.35vw, 1.1rem); line-height: 1.75; }

/* ===== Sections ===== */
.section { padding: 24px 0; }
.section-title { font-size: clamp(1.35rem, 2.1vw, 1.75rem); font-weight: 700; margin-bottom: 24px; color: $(primary.dark); display: flex; align-items: center; gap: 8px; }
.section-title::after { content: ''; flex: 1; height: 2px; background: $(border.color); }

/* ===== Property Cards Grid (3 / 2 / 1) ===== */
.property-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  width: 100%;
  min-width: 0;
  align-items: stretch;
}
@media (min-width: 1100px) {
  .property-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
/* Neutralise the Blogger Blog widget wrapper so it does not collapse the grid into one cell */
.blog-posts, .blog-posts > .section, .blog-posts > .widget, .blog-posts > .widget > .widget-content {
  display: block; width: 100%; max-width: 100%; min-width: 0;
}
.blog-posts > .widget > h2 { display: none; }
.property-grid > .property-card { min-width: 0; width: 100%; max-width: none; }

.property-card {
  background: $(card.bg);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,.06);
  transition: transform .2s ease, box-shadow .2s ease;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.property-card:hover { transform: translateY(-4px); box-shadow: 0 8px 24px rgba(0,0,0,.12); }
.property-card .card-body { padding: 16px; flex: 1; display: flex; flex-direction: column; min-width: 0; }
.property-card .card-title { font-size: 1.1rem; font-weight: 700; margin-bottom: 8px; color: $(text.color); overflow-wrap: anywhere; }
.property-card .card-title a { color: $(text.color); }
.property-card .card-title a:hover { color: $(primary.color); }

/* ===== Card photo carousel ===== */
.property-photo-carousel { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: $(border.color); touch-action: pan-y pinch-zoom; user-select: none; -webkit-user-select: none; }
.property-photo-carousel .property-photo-link { display: block; width: 100%; height: 100%; }
.property-photo-carousel .card-image { width: 100%; height: 100%; object-fit: cover; display: block; }
.property-photo-carousel .carousel-current-image { pointer-events: none; }
.property-photo-carousel .carousel-empty { display: flex; align-items: center; justify-content: center; color: #999; font-size: .9rem; }
.property-photo-carousel .photo-nav {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 2;
  width: 34px; height: 34px; border: 0; border-radius: 50%; background: rgba(255,255,255,.9);
  color: #333; font-size: 25px; line-height: 1; cursor: pointer; box-shadow: 0 1px 5px rgba(0,0,0,.18);
  display: flex; align-items: center; justify-content: center;
}
.property-photo-carousel .photo-prev { left: 10px; }
.property-photo-carousel .photo-next { right: 10px; }
.property-photo-carousel .photo-nav:disabled { opacity: .35; cursor: default; }
.property-photo-carousel .photo-counter { position: absolute; bottom: 10px; right: 10px; padding: 3px 8px; border-radius: 12px; background: rgba(0,0,0,.62); color: #fff; font-size: 12px; direction: ltr; }
.property-photo-carousel[data-image-count='1'] .photo-nav,
.property-photo-carousel[data-image-count='1'] .photo-counter { display: none; }

/* ===== Card features + status badge ===== */
.card-meta.property-features { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 10px 0; margin: 0 0 8px; border-bottom: 1px solid $(border.color); }
.property-features .feature-item { display: inline-flex; align-items: center; gap: 4px; color: $(muted.color); font-size: .82rem; }
.property-features .feature-icon { font-size: 1rem; display: inline-flex; align-items: center; }
.property-features .feature-icon svg { width: 1.05em; height: 1.05em; }
.property-features .feature-status { margin-inline-start: auto; border-radius: 4px; padding: 3px 8px; font-size: .78rem; font-weight: 700; background: #f1f3f4; color: #5f6368; white-space: nowrap; }
.property-features .feature-status.is-available { background: #e5f6eb; color: #137333; }
.property-features .feature-status.is-unavailable { background: #fce8e6; color: #c5221f; }

/* ===== Price (final, USD) ===== */
.property-card .card-price { display: block; min-height: 1.5em; font-size: 1.35rem; line-height: 1.5; font-weight: 800; color: $(primary.color); padding: 4px 0 8px; overflow-wrap: anywhere; }
.property-card .card-price .darna-price-value { display: inline-block; }
.property-card .card-link { margin-top: auto; background: $(primary.color); color: #fff; text-align: center; padding: 10px; border-radius: 8px; font-weight: 600; font-size: .9rem; transition: background .2s ease; }
.property-card .card-link:hover { background: $(primary.dark); color: #fff; }

/* ===== Detail page ===== */
.property-detail { padding: 12px 0 28px; }
.detail-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 28px; align-items: start; }
@media (max-width: 980px) { .detail-grid { grid-template-columns: minmax(0, 1fr); } }
.detail-title { font-size: 1.8rem; font-weight: 800; margin-bottom: 10px; overflow-wrap: anywhere; }
.property-rating { margin-top: 24px; padding: 18px; background: $(card.bg); border: 1px solid $(border.color); border-radius: 12px; }
.property-rating .section-title { font-size: 1.15rem; margin-bottom: 8px; }
.rating-stars { display: flex; direction: ltr; gap: 4px; }
.rating-stars button { border: 0; background: transparent; color: #c7d0d6; cursor: pointer; font-size: 1.8rem; line-height: 1; padding: 4px; border-radius: 6px; }
.rating-stars button:hover, .rating-stars button:focus-visible, .rating-stars button.is-selected { color: $(accent.color); }
.rating-stars button:focus-visible { outline: 3px solid rgba(201,150,43,.35); outline-offset: 2px; }
.rating-status { margin-top: 8px; color: $(muted.color); font-size: .84rem; }
.detail-tags { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.detail-tags .detail-tag { background: $(card.bg); border: 1px solid $(border.color); padding: 4px 12px; border-radius: 6px; font-size: .82rem; color: $(muted.color); }
.detail-tags .detail-tag:hover { border-color: $(primary.color); color: $(primary.color); }

.gallery-container { margin-bottom: 24px; }
.gallery-main { position: relative; width: 100%; aspect-ratio: 16 / 10; border-radius: 12px; overflow: hidden; background: $(border.color); touch-action: pan-y pinch-zoom; }
.gallery-main img { width: 100%; height: 100%; object-fit: cover; }
.gallery-btn { position: absolute; top: 50%; transform: translateY(-50%); background: rgba(0,0,0,.5); color: #fff; border: none; width: 42px; height: 42px; border-radius: 50%; font-size: 1.3rem; cursor: pointer; display: flex; align-items: center; justify-content: center; z-index: 2; }
.gallery-btn:hover { background: rgba(0,0,0,.72); }
.gallery-btn.prev { left: 12px; }
.gallery-btn.next { right: 12px; }
.gallery-btn:disabled { opacity: .35; cursor: default; }
.gallery-counter { position: absolute; bottom: 12px; right: 12px; background: rgba(0,0,0,.62); color: #fff; padding: 4px 10px; border-radius: 12px; font-size: .8rem; direction: ltr; }
.gallery-nav { display: flex; gap: 8px; margin-top: 8px; overflow-x: auto; padding-bottom: 4px; }
.gallery-thumb { width: 84px; height: 62px; object-fit: cover; border-radius: 6px; cursor: pointer; border: 2px solid transparent; flex-shrink: 0; transition: border-color .2s ease; }
.gallery-thumb.active { border-color: $(primary.color); }

/* ===== Specs bar ===== */
.detail-specs { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 12px; margin: 20px 0; }
.spec-item { background: $(card.bg); border: 1px solid $(border.color); border-radius: 10px; padding: 14px 10px; text-align: center; }
.spec-item .spec-icon { font-size: 1.4rem; display: block; margin-bottom: 4px; }
.spec-item .spec-value { font-weight: 700; font-size: 1.05rem; display: block; }
.spec-item .spec-label { font-size: .78rem; color: $(muted.color); }

/* ===== Detail price card / sidebar ===== */
.detail-side { position: sticky; top: 90px; }
@media (max-width: 980px) { .detail-side { position: static; } }
.detail-price-card { background: $(card.bg); border: 1px solid $(border.color); border-radius: 12px; padding: 20px; box-shadow: 0 2px 10px rgba(0,0,0,.05); }
.detail-price { font-size: 1.7rem; font-weight: 800; color: $(primary.color); margin-bottom: 6px; }
.detail-status { display: inline-block; border-radius: 6px; padding: 4px 12px; font-size: .85rem; font-weight: 700; margin-bottom: 14px; background: #f1f3f4; color: #5f6368; }
.detail-status.is-available { background: #e5f6eb; color: #137333; }
.detail-status.is-unavailable { background: #fce8e6; color: #c5221f; }

/* ===== Inquiry / contact form ===== */
.inquiry-form { margin-top: 18px; display: grid; gap: 10px; }
.inquiry-form .field { display: grid; gap: 4px; }
.inquiry-form label { font-size: .82rem; font-weight: 600; color: $(text.color); }
.inquiry-form input, .inquiry-form select, .inquiry-form textarea {
  width: 100%; padding: 9px 12px; border: 1px solid $(border.color); border-radius: 8px;
  font-family: inherit; font-size: .9rem; background: #fff; color: $(text.color);
}
.inquiry-form textarea { min-height: 84px; resize: vertical; }
.inquiry-form input:focus, .inquiry-form select:focus, .inquiry-form textarea:focus { outline: 3px solid rgba(201,150,43,.35); border-color: $(accent.color); }
.inquiry-form .field.invalid input, .inquiry-form .field.invalid select { border-color: #c5221f; }
.inquiry-form .field-error { color: #c5221f; font-size: .76rem; min-height: 1em; }
.inquiry-form .form-submit { background: $(whatsapp.color); color: #fff; border: none; padding: 12px; border-radius: 10px; font-weight: 700; font-size: 1rem; cursor: pointer; font-family: inherit; }
.inquiry-form .form-submit:hover { opacity: .92; }
.inquiry-form .form-note { font-size: .76rem; color: $(muted.color); margin-top: 2px; }
.inquiry-form .form-success { background: #e5f6eb; color: #137333; border-radius: 8px; padding: 10px 12px; font-size: .85rem; }
.whatsapp-cta { display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: $(whatsapp.color); color: #062f1b; padding: 12px 20px; border-radius: 10px; font-weight: 700; font-size: .95rem; width: 100%; margin-bottom: 14px; }
.whatsapp-cta:hover { opacity: .92; color: #062f1b; }
.whatsapp-note { font-size: .78rem; color: $(muted.color); margin-top: 8px; }
.whatsapp-float { position: fixed; bottom: 18px; inset-inline-end: 18px; z-index: 260; width: 56px; height: 56px; border-radius: 50%; background: $(whatsapp.color); color: #fff; display: flex; align-items: center; justify-content: center; box-shadow: 0 6px 18px rgba(0,0,0,.25); transition: transform .2s ease, box-shadow .2s ease; }
.whatsapp-float:hover { transform: scale(1.06); color: #fff; box-shadow: 0 8px 22px rgba(0,0,0,.3); }
.whatsapp-float svg { width: 28px; height: 28px; }
body:has(.compare-bar:not([hidden])) .whatsapp-float { bottom: 74px; }
@media (max-width: 768px) { .whatsapp-float { width: 52px; height: 52px; bottom: 14px; inset-inline-end: 14px; } .whatsapp-float svg { width: 26px; height: 26px; } }

/* ===== Body content (description / amenities) ===== */
.post-body { line-height: 1.9; overflow-wrap: anywhere; }
.post-body p { margin-bottom: 12px; }
.post-body h2, .post-body h3 { margin: 22px 0 10px; font-weight: 700; color: $(primary.dark); }
.post-body ul { padding-inline-start: 20px; list-style: disc; margin-bottom: 12px; }
.post-body li { margin-bottom: 4px; }
.post-body img { border-radius: 10px; margin: 8px 0; }
.post-body table { width: 100%; border-collapse: collapse; margin: 12px 0; }
.post-body td, .post-body th { border: 1px solid $(border.color); padding: 8px; text-align: start; }

/* ===== Similar properties ===== */
.similar-section { margin-top: 36px; }
.similar-section .property-grid { grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); }

/* ===== Filters ===== */

/* ===== Filter chips bar ===== */
.filter-bar { display: flex; gap: 8px; flex-wrap: wrap; padding: 8px 0; align-items: center; }
.filter-bar .filter-label { font-weight: 600; font-size: .9rem; color: $(muted.color); }
.filter-bar .filter-chip { background: $(card.bg); border: 1px solid $(border.color); padding: 6px 14px; border-radius: 20px; font-size: .85rem; color: $(text.color); transition: all .2s ease; }
.filter-bar .filter-chip:hover, .filter-bar .filter-chip.active { background: $(primary.color); color: #fff; border-color: $(primary.color); }

/* ===== No results / loading ===== */
.no-results, .loading-state { text-align: center; padding: 40px; color: $(muted.color); font-size: 1.1rem; }

/* ===== Pagination ===== */
.pagination { display: flex; justify-content: center; gap: 4px; padding: 24px 0; flex-wrap: wrap; }
.pagination a, .pagination span { padding: 8px 14px; border-radius: 6px; font-size: .9rem; font-weight: 600; border: 1px solid $(border.color); background: $(card.bg); color: $(text.color); }
.pagination a:hover { background: $(primary.color); color: #fff; border-color: $(primary.color); }
.pagination .current-page { background: $(primary.color); color: #fff; border-color: $(primary.color); }

/* ===== Sidebar widgets ===== */
.sidebar { display: flex; flex-direction: column; gap: 20px; }
.widget-card { background: $(card.bg); border-radius: 12px; padding: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.04); }
.widget-card h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 12px; color: $(primary.dark); }
.widget-card ul li { padding: 6px 0; border-bottom: 1px solid $(border.color); font-size: .9rem; }
.widget-card ul li:last-child { border-bottom: none; }
.widget-card img { border-radius: 8px; }
.ad-slot { background: $(bg.color); border: 2px dashed $(border.color); border-radius: 8px; padding: 20px; text-align: center; color: $(muted.color); font-size: .85rem; min-height: 90px; display: flex; align-items: center; justify-content: center; }

/* ===== Generic post / static page ===== */
.post { background: $(card.bg); border-radius: 12px; padding: 24px; margin-bottom: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.04); }
.post-title { font-size: 1.5rem; font-weight: 700; margin-bottom: 12px; }
.post-meta { font-size: .8rem; color: $(muted.color); margin-bottom: 16px; }

/* ===== Footer ===== */
.site-footer { background: $(footer.bg); color: rgba(255,255,255,.8); padding: 16px 0 16px; margin-top: 14px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; margin-bottom: 18px; }
.footer-grid h4 { color: #fff; font-size: 1rem; font-weight: 700; margin-bottom: 12px; }
.footer-grid ul li { padding: 4px 0; }
.footer-grid ul li a { color: rgba(255,255,255,.7); font-size: .9rem; }
.footer-grid ul li a:hover { color: #fff; }
.footer-contact { font-size: .9rem; }
.footer-contact a { color: $(whatsapp.color); font-weight: 600; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,.15); padding-top: 12px; text-align: center; font-size: .85rem; color: rgba(255,255,255,.82); }
.footer-widgets .widget { color: rgba(255,255,255,.8); margin-bottom: 16px; }
.footer-widgets .widget h2 { color: #fff; font-size: 1rem; font-weight: 700; margin-bottom: 10px; }

/* ===== Main content layout ===== */
.main-content { display: flex; gap: 24px; padding: 18px 0; }
.content-area { flex: 1; min-width: 0; }
.sidebar-area { width: 300px; flex-shrink: 0; }

/* ===== RTL ===== */
html[dir="rtl"] .gallery-btn.prev { left: auto; right: 12px; }
html[dir="rtl"] .gallery-btn.next { right: auto; left: 12px; }
html[dir="rtl"] .property-photo-carousel .photo-prev { left: auto; right: 10px; }
html[dir="rtl"] .property-photo-carousel .photo-next { right: auto; left: 10px; }

/* ===== Place-dj identity, header tools and Airbnb-like preferred cards ===== */
.site-logo .logo-icon { width: clamp(84px, 8.5vw, 108px); height: auto; aspect-ratio: 300 / 165; padding: 0; border-radius: 0; background: transparent; display: flex; align-items: center; justify-content: flex-start; overflow: visible; }
.site-logo .brand-logo, .footer-brand .brand-logo { display: block; width: 100%; height: auto; max-width: 100%; object-fit: contain; object-position: center; }
.footer-brand { display: inline-flex; width: min(150px, 100%); max-width: 150px; padding: 0; border-radius: 0; background: transparent; }
.header-tools { display: flex; align-items: center; gap: 8px; }
.lang-switch { display: inline-flex; align-items: center; gap: 6px; flex: 0 0 auto; min-width: max-content; white-space: nowrap; }
.lang-switch .lang-link { display: inline-flex; align-items: center; justify-content: center; width: 38px; height: 38px; min-width: 38px; padding: 0; box-sizing: border-box; background: rgba(255,255,255,.12); color: #fff; border: 1px solid rgba(255,255,255,.32); border-radius: 8px; text-decoration: none; cursor: pointer; }
.lang-switch .lang-link svg { display: block; width: 22px; height: 16px; flex: 0 0 auto; }
.lang-switch .lang-link:hover, .lang-switch .lang-link:focus-visible { background: rgba(255,255,255,.24); outline: 2px solid #12AD2B; outline-offset: 1px; }
.social-links { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.social-icon { display: inline-flex; align-items: center; justify-content: center; width: 38px; height: 38px; padding: 0; border: 1px solid rgba(255,255,255,.28); border-radius: 9px; color: rgba(255,255,255,.84); transition: color .2s ease, background-color .2s ease, border-color .2s ease, transform .2s ease; }
.social-icon:hover, .social-icon:focus-visible { color: #fff; background: rgba(18,173,43,.18); border-color: #12AD2B; transform: translateY(-1px); outline: none; }
.social-icon svg { width: 19px; height: 19px; fill: currentColor; display: block; }
.social-note { margin-top: 8px; color: rgba(255,255,255,.78); font-size: .72rem; }
.lang-switch .lang-link[aria-current='page'] { box-shadow: inset 0 0 0 2px #12AD2B; }
.icon-btn { position: relative; background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.32); color: #fff; border-radius: 8px; width: 38px; height: 38px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.icon-btn:hover { background: rgba(255,255,255,.24); }
.icon-btn .fav-badge { position: absolute; top: -6px; inset-inline-end: -6px; background: #D7141A; color: #fff; font-size: 11px; min-width: 18px; height: 18px; border-radius: 9px; display: inline-flex; align-items: center; justify-content: center; padding: 0 4px; }

.card-loc { display: flex; align-items: center; gap: 4px; color: $(muted.color); font-size: .82rem; margin-bottom: 4px; }
.card-loc .loc-icon { display: inline-flex; align-items: center; }
.card-loc .loc-icon svg { width: 1em; height: 1em; }
.property-card .card-desc { color: $(muted.color); font-size: .85rem; line-height: 1.6; margin: 6px 0 10px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.property-photo-carousel .card-type { position: absolute; top: 10px; inset-inline-start: 10px; z-index: 3; padding: 3px 10px; border-radius: 4px; font-size: .78rem; font-weight: 700; color: #fff; background: rgba(13,110,168,.92); box-shadow: 0 1px 4px rgba(0,0,0,.2); }
.property-photo-carousel .card-fav, .property-photo-carousel .card-compare { position: absolute; top: 10px; z-index: 3; width: 34px; height: 34px; border-radius: 50%; border: 0; background: rgba(255,255,255,.92); color: #444; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; box-shadow: 0 1px 5px rgba(0,0,0,.18); }
.property-photo-carousel .card-fav { inset-inline-end: 10px; }
.property-photo-carousel .card-compare { inset-inline-end: 50px; }
.property-photo-carousel .card-fav.is-active { color: #D7141A; }
.property-photo-carousel .card-compare.is-active { color: $(primary.color); }
.property-photo-carousel .card-fav svg, .property-photo-carousel .card-compare svg { width: 18px; height: 18px; }
.property-photo-carousel .card-image.is-broken { background: $(border.color); }

.detail-actions { display: flex; gap: 8px; margin-bottom: 14px; flex-wrap: wrap; }
.detail-actions .detail-btn { flex: 1; min-width: 130px; display: inline-flex; align-items: center; justify-content: center; gap: 6px; background: $(bg.color); border: 1px solid $(border.color); color: $(text.color); padding: 10px 12px; border-radius: 8px; font-weight: 600; font-size: .85rem; cursor: pointer; font-family: inherit; }
.detail-actions .detail-btn.is-active { border-color: $(primary.color); color: $(primary.color); }
.detail-actions .detail-fav.is-active { border-color: #D7141A; color: #D7141A; }
.detail-type { display: inline-block; background: $(bg.color); border: 1px solid $(border.color); color: $(muted.color); border-radius: 6px; padding: 4px 12px; font-size: .82rem; margin-bottom: 14px; }
.price-includes { font-size: .82rem; color: $(muted.color); margin: 2px 0 14px; }

.discovery-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; margin-bottom: 24px; }
.discovery-card { background: $(card.bg); border: 1px solid $(border.color); border-radius: 12px; padding: 16px; text-align: center; color: $(text.color); transition: transform .2s ease, border-color .2s ease; }
.discovery-card:hover { transform: translateY(-3px); border-color: $(primary.color); color: $(primary.color); }
.discovery-card .discovery-icon { color: #6b7780; display: grid; place-items: center; width: 2.25rem; height: 2.25rem; margin: 0 auto 8px; }
.discovery-card .discovery-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.discovery-card:hover .discovery-icon, .discovery-card:focus-visible .discovery-icon { color: $(primary.color); }
.discovery-card .discovery-name { font-weight: 700; font-size: clamp(.98rem, 1.1vw, 1.08rem); }
.discovery-card small { display: block; color: $(muted.color); font-size: .82rem; line-height: 1.45; margin-top: 5px; }
.section-note { color: $(muted.color); font-size: clamp(.88rem, 1.1vw, .98rem); margin: -12px 0 16px; }
.preferred-carousel { position: relative; display: block; width: 100%; }
.preferred-viewport { direction: ltr; width: 100%; min-width: 0; overflow-x: auto; overflow-y: hidden; padding: 2px 1px 12px; touch-action: pan-x pan-y; overscroll-behavior-x: contain; scroll-behavior: smooth; scroll-snap-type: x mandatory; scrollbar-width: none; }
.preferred-viewport::-webkit-scrollbar { display: none; }
.preferred-strip { display: flex; gap: 14px; width: 100%; min-width: 100%; direction: ltr; }
.preferred-card { direction: rtl; scroll-snap-align: start; flex: 0 0 calc((100% - 28px) / 3); min-width: 0; background: $(card.bg); border: 1px solid rgba(0,0,0,.08); border-radius: 16px; overflow: hidden; color: $(text.color); box-shadow: 0 2px 12px rgba(0,0,0,.08); text-decoration: none; }
.preferred-card img { width: 100%; aspect-ratio: 4 / 3; min-height: 150px; object-fit: cover; display: block; background: $(border.color); }
.preferred-card span { display: block; padding: 12px 13px 14px; }
.preferred-card strong { display: block; font-size: clamp(.96rem, 1.15vw, 1.08rem); line-height: 1.45; }
.preferred-card small { display: block; color: $(muted.color); font-size: clamp(.82rem, .95vw, .92rem); line-height: 1.55; margin-top: 5px; }
.preferred-card:hover, .preferred-card:focus-visible { border-color: $(primary.color); color: $(text.color); box-shadow: 0 7px 22px rgba(0,0,0,.13); }
.preferred-nav { position: absolute; top: 42%; z-index: 2; width: 40px; height: 40px; border: 1px solid rgba(0,0,0,.12); border-radius: 50%; background: rgba(255,255,255,.96); color: $(primary.dark); cursor: pointer; font-size: 1.8rem; line-height: 1; box-shadow: 0 3px 12px rgba(0,0,0,.16); display: inline-flex; align-items: center; justify-content: center; }
.preferred-prev { inset-inline-start: 12px; }
.preferred-next { inset-inline-end: 12px; }
.preferred-nav:hover, .preferred-nav:focus-visible { background: $(primary.color); color: #fff; }
.popular-list li { display: flex; align-items: center; gap: 10px; }
.popular-list .popular-thumb { width: 58px; height: 42px; flex: 0 0 58px; object-fit: cover; border-radius: 7px; background: $(border.color); }
.popular-list .popular-link { min-width: 0; overflow-wrap: anywhere; }

.add-property-card { background: linear-gradient(135deg, $(primary.color), $(primary.dark)); color: #fff; border-radius: 14px; padding: 32px 24px; text-align: center; }
.add-property-card h2 { font-size: 1.4rem; margin-bottom: 8px; }
.add-property-card p { opacity: .92; max-width: 620px; margin: 0 auto 18px; }
.add-property-btn { display: inline-block; background: $(accent.color); color: #062f1b; padding: 12px 30px; border-radius: 10px; font-weight: 700; }
.add-property-btn:hover { color: #062f1b; opacity: .94; }
.add-property-btn.is-placeholder { cursor: not-allowed; }
.add-property-note { font-size: .78rem; opacity: .8; margin-top: 12px; }

.placedj-panel { position: fixed; top: 0; inset-inline-end: 0; width: min(380px, 92vw); height: 100%; background: $(card.bg); box-shadow: -4px 0 24px rgba(0,0,0,.18); z-index: 300; overflow-y: auto; padding: 18px; }
.placedj-panel-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.placedj-panel-head h2 { font-size: 1.15rem; color: $(primary.dark); }
.placedj-close { background: none; border: 0; font-size: 1.5rem; cursor: pointer; color: $(muted.color); line-height: 1; }
.fav-item { display: flex; gap: 10px; align-items: center; padding: 10px 0; border-bottom: 1px solid $(border.color); }
.fav-thumb { width: 64px; height: 48px; border-radius: 8px; overflow: hidden; flex-shrink: 0; background: $(bg.color); display: flex; align-items: center; justify-content: center; }
.fav-thumb img { width: 100%; height: 100%; object-fit: cover; }
.fav-noimg { font-size: .7rem; color: $(muted.color); }
.fav-info { flex: 1; min-width: 0; }
.fav-title { display: block; font-weight: 700; font-size: .9rem; color: $(text.color); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fav-meta { font-size: .76rem; color: $(muted.color); }
.fav-price { font-size: .85rem; font-weight: 700; color: $(primary.color); }
.fav-remove { background: none; border: 0; color: $(muted.color); font-size: 1.2rem; cursor: pointer; }
.fav-empty, .compare-empty { color: $(muted.color); font-size: .9rem; text-align: center; padding: 20px 0; }

.compare-bar { position: fixed; bottom: 0; inset-inline: 0; background: $(primary.dark); color: #fff; padding: 10px 16px; display: flex; align-items: center; gap: 12px; justify-content: center; z-index: 250; flex-wrap: wrap; }
.compare-bar button { border: 0; border-radius: 8px; padding: 8px 18px; font-weight: 700; cursor: pointer; font-family: inherit; }
.compare-bar .compare-open { background: $(accent.color); color: #fff; }
.compare-bar .compare-clear { background: rgba(255,255,255,.16); color: #fff; }
.placedj-modal { position: fixed; inset: 0; background: rgba(0,0,0,.55); z-index: 320; display: flex; align-items: center; justify-content: center; padding: 16px; }
.placedj-modal .modal-inner { background: $(card.bg); border-radius: 14px; width: min(960px, 96vw); max-height: 88vh; overflow: auto; padding: 20px; position: relative; }
.placedj-modal .modal-close { position: absolute; top: 10px; inset-inline-end: 14px; background: none; border: 0; font-size: 1.6rem; cursor: pointer; color: $(muted.color); }
.compare-scroll { overflow-x: auto; }
.compare-table { width: 100%; border-collapse: collapse; min-width: 560px; }
.compare-table th, .compare-table td { border: 1px solid $(border.color); padding: 10px; text-align: start; font-size: .85rem; vertical-align: top; }
.compare-table thead th { background: $(bg.color); }
.compare-table tbody th { background: $(bg.color); white-space: nowrap; }
.cmp-head { display: flex; flex-direction: column; gap: 6px; align-items: center; text-align: center; }
.cmp-head img { width: 100%; max-width: 140px; height: 90px; object-fit: cover; border-radius: 8px; }
.cmp-head a { font-weight: 700; color: $(text.color); font-size: .85rem; }
.cmp-remove { background: none; border: 0; color: $(muted.color); font-size: 1.1rem; cursor: pointer; }
.cmp-na { color: $(muted.color); font-style: italic; }

.comments-section { margin-top: 36px; }
.comments-section .comments { background: $(card.bg); border-radius: 12px; padding: 20px; }
.comments-section .comments h3, .comments-section .comments h4 { color: $(primary.dark); margin-bottom: 10px; }
.comments-section iframe { width: 100%; border: 0; }


/* ===== Filters restored from the source theme ===== */
.sidebar-filter-wrap { margin-bottom: 18px; }
.darna-filters { background: $(card.bg); border: 1px solid $(border.color); border-radius: 12px; padding: 16px; margin-bottom: 24px; box-shadow: 0 2px 8px rgba(0,0,0,.04); }
.darna-filters .filters-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; align-items: end; }
.darna-filters .filter-field { display: grid; gap: 4px; }
.darna-filters .filter-field label { font-size: .78rem; font-weight: 600; color: $(muted.color); }
.darna-filters input, .darna-filters select { width: 100%; padding: 9px 12px; border: 1px solid $(border.color); border-radius: 8px; font-family: inherit; font-size: .88rem; background: #fff; color: $(text.color); }
.darna-filters input:focus, .darna-filters select:focus { outline: 3px solid rgba(201,150,43,.35); border-color: $(accent.color); }
.darna-filters .filter-actions { display: flex; gap: 8px; align-items: end; }
.darna-filters .filter-apply { background: $(primary.color); border: 1px solid $(primary.color); color: #fff; padding: 9px 18px; border-radius: 8px; font-weight: 600; cursor: pointer; font-family: inherit; font-size: .88rem; }
.darna-filters .filter-reset { background: $(bg.color); border: 1px solid $(border.color); color: $(text.color); padding: 9px 16px; border-radius: 8px; font-weight: 600; cursor: pointer; font-family: inherit; font-size: .88rem; }
.darna-filters .filter-reset:hover { border-color: $(primary.color); color: $(primary.color); }
.darna-filters .filters-status { margin-top: 12px; font-size: .85rem; color: $(muted.color); }
.darna-filters .filters-status strong { color: $(primary.dark); }
.filters-scope { font-size: .78rem; color: $(muted.color); margin-bottom: 10px; }
.filters-disclosure { margin: 0; }
.filters-disclosure > summary.filters-summary { cursor: pointer; font-weight: 700; color: $(primary.dark); padding: 6px 0; list-style: none; display: flex; align-items: center; gap: 6px; }
.filters-disclosure > summary.filters-summary::-webkit-details-marker { display: none; }
.filters-disclosure > summary.filters-summary::before { content: '\25B8'; font-size: .95rem; transition: transform .2s ease; }
.filters-disclosure[open] > summary.filters-summary::before { transform: rotate(90deg); }
@media (min-width: 769px) { .filters-disclosure > summary.filters-summary { display: none; } }
@media (max-width: 768px) { .darna-filters { padding: 12px; } .darna-filters .filters-row { grid-template-columns: repeat(2, minmax(0, 1fr)); } .darna-filters .filter-field:first-child { grid-column: 1 / -1 !important; } .darna-filters .filter-actions { grid-column: 1 / -1; } }

/* ===== Responsive ===== */
@media (min-width: 769px) and (max-width: 1199px) {
  .preferred-card { flex-basis: calc((100% - 28px) / 3); }
}
@media (min-width: 769px) and (max-width: 1100px) {
  .header-inner { display: grid; grid-template-columns: auto auto minmax(220px, 1fr) auto; grid-template-areas: "logo menu search tools"; gap: 10px; }
  .site-logo { grid-area: logo; }
  .nav-toggle { grid-area: menu; display: inline-flex; align-items: center; }
  .search-bar { grid-area: search; min-width: 0; }
  .header-tools { grid-area: tools; }
  .main-nav { display: none; order: 5; width: 100%; flex-direction: column; padding: 8px 0; }
  .main-nav.open { display: flex; }
  .main-nav a { width: 100%; }
  .main-content { flex-direction: column; }
  .content-area, .sidebar-area { width: 100%; }
  .sidebar-area { order: 2; }
}
@media (max-width: 768px) {
  .header-inner { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "logo menu tools" "search search search" "nav nav nav"; gap: 8px; align-items: center; padding: 8px 0 10px; }
  .site-logo { grid-area: logo; min-width: 0; }
  .site-logo .logo-icon { width: min(122px, 34vw); height: 50px; }
  .nav-toggle { grid-area: menu; display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; padding: 0; }
  .header-tools { grid-area: tools; width: auto; justify-content: flex-end; gap: 6px; min-width: 0; }
  .lang-switch { gap: 3px; }
  .lang-switch .lang-link { width: 36px; height: 36px; min-width: 36px; }
  .lang-switch .lang-link svg { width: 21px; height: 15px; }
  .icon-btn { width: 36px; height: 36px; }
  .main-nav { grid-area: nav; display: none; width: 100%; flex-direction: column; padding: 8px 0 0; }
  .main-nav.open { display: flex; }
  .main-nav a { width: 100%; }
  .search-bar { grid-area: search; width: 100%; min-width: 0; flex-basis: auto; order: initial; }
  .search-bar input[type="text"], .search-bar input[type="search"] { flex: 1; }
  .home-intro { margin-top: 12px; padding: 16px 14px; border-radius: 14px; }
  .home-intro h1 { font-size: clamp(1.3rem, 6vw, 1.7rem); }
  .home-intro p { font-size: clamp(.9rem, 3.6vw, 1rem); line-height: 1.7; }
  .hero-slider { aspect-ratio: 16 / 9; min-height: 150px; max-height: 215px; border-radius: 12px; touch-action: pan-y pinch-zoom; }
  .hero-copy { padding: 12px 8%; align-items: center; justify-content: center; }
  .hero-copy h1 { font-size: clamp(1.15rem, 6vw, 1.65rem); line-height: 1.25; margin-bottom: 6px; text-align: center; }
  .hero-copy p { max-width: 31rem; font-size: clamp(.82rem, 3.35vw, .98rem); line-height: 1.55; text-align: center; }
  .preferred-strip { gap: 12px; }
  .preferred-viewport { padding-inline: 4px; }
  .preferred-card { flex-basis: 100%; border-radius: 15px; }
  .preferred-nav { width: 36px; height: 36px; font-size: 1.55rem; }
  .preferred-prev { inset-inline-start: 8px; }
  .preferred-next { inset-inline-end: 8px; }
  .property-grid { grid-template-columns: minmax(0, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
  .footer-grid > div:first-child, .footer-grid > div:nth-child(4) { grid-column: 1 / -1; }
  .footer-grid > div:nth-child(2) { grid-column: 1; grid-row: 2; }
  .footer-grid > div:nth-child(3) { grid-column: 2; grid-row: 2; }
  .footer-grid > div:nth-child(4) { grid-row: 3; }
  .main-content { flex-direction: column; }
  .content-area, .sidebar-area, .sidebar-filter-wrap { display: contents; }
  .home-before-posts { order: 10; }
  .preferred-section { order: 20; }
  .main { order: 30; }
  .sidebar-filter-wrap #darna-filters { order: 35; }
  .filter-layout-controls { order: 36; }
  .discovery-section { order: 40; }
  .discovery-section + .section { order: 50; }
  .home-after-posts { order: 60; }
  #sidebar-widgets { order: 70; }
  .sidebar-area { width: 100%; }
  .detail-side { position: static; }
}
@media (min-width: 769px) and (max-width: 1099px) {
  .property-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1500px) {
  .container { max-width: 1320px; }
  .property-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (max-width: 768px) {
  .header-inner { gap: 10px; }
  .header-tools { width: auto; justify-content: flex-end; }
  .compare-bar { font-size: .85rem; }
}

@media (min-width: 769px) and (max-width: 1199px) {
  .site-logo .logo-icon { width: 76px; }
}
@media (max-width: 768px) {
  .site-logo .logo-icon { width: 74.8px; height: auto; margin-right: 4px; }
  .footer-brand { width: 120px; max-width: 80%; margin-inline-start: auto; margin-inline-end: 0; }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
  html { scroll-behavior: auto; }
}

/* ===== Focus visibility ===== */
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 3px solid $(accent.color);
  outline-offset: 2px;
}

/* ===== Structured data holder ===== */
.structured-data { display: none; }

head.b:template-skin:

body { min-height: 100vh; display: flex; flex-direction: column; }
#main-wrapper { flex: 1 0 auto; }
body#layout { display: block !important; min-height: 0 !important; }

body.script:
//
(function () {
  'use strict';

  /* ================= Arabic text normalisation (matching only) ================= */
  function darnaNorm(s) {
    return String(s == null ? '' : s)
      .replace(/[\u064B-\u0652\u0640]/g, '')
      .replace(/[\u0622\u0623\u0625\u0627]/g, '\u0627')
      .replace(/\u0649/g, '\u064A')
      .replace(/\u0629/g, '\u0647')
      .replace(/\u0624/g, '\u0648')
      .replace(/\u0626/g, '\u064A')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  /* ================= Unified price logic (single source of truth) =================
     Recorded-price convention (Blogger post labels; separator may be ':' '-' or '_'):
       price:100       -> quoted price displayed as entered (no automatic fee)
       pricefinal:110  -> final price ALREADY including the 10% fee    -> displayed as-is (no extra)
       cur:USD         -> currency code (default USD)
       per:night       -> pricing unit (night|day|week|month|stay)
     Never add an automatic fee to owner-entered prices. Never fabricate a price and never hide the numeric price. */
  var DARNA_SERVICE_FEE_RATE = 0;
  var DARNA_PRICE_LABEL_RE = /^(pricefinal|price|cur|per)\s*[:\-_]\s*(.+)$/i;
  var DARNA_CUR_SYMBOL = { USD: '$', EUR: '\u20AC', GBP: '\u00A3', JPY: '\u00A5', CNY: '\u00A5', INR: '\u20B9', NGN: '\u20A6', TRY: '\u20BA', RUB: '\u20BD', KRW: '\u20A9', MRU: 'UM', DJF: 'Fdj', SAR: 'SR', AED: 'AED', EGP: 'E\u00A3', MAD: 'MAD', QAR: 'QR', KWD: 'KD' };
  var DARNA_UNITS = {
    ar: { night: '\u0644\u064A\u0644\u0629', day: '\u064A\u0648\u0645', week: '\u0623\u0633\u0628\u0648\u0639', month: '\u0634\u0647\u0631', stay: '\u0645\u062F\u0629 \u0627\u0644\u0625\u0642\u0627\u0645\u0629' },
    en: { night: 'night', day: 'day', week: 'week', month: 'month', stay: 'stay' },
    fr: { night: 'nuit', day: 'jour', week: 'semaine', month: 'mois', stay: 's\u00E9jour' }
  };

  function darnaParsePriceLabels(labels) {
    var out = { base: null, final: null, cur: 'USD', per: '' };
    (labels || []).forEach(function (raw) {
      if (raw == null) return;
      var normalized = String(raw).replace(/[\u00A0\u200B\uFEFF]/g, '').trim();
      var m = DARNA_PRICE_LABEL_RE.exec(normalized);
      if (!m) return;
      var key = m[1].toLowerCase();
      var val = m[2].trim();
      if (key === 'price') out.base = val;
      else if (key === 'pricefinal') out.final = val;
      else if (key === 'cur') out.cur = val.toUpperCase();
      else if (key === 'per') out.per = val.toLowerCase();
    });
    return out;
  }

  function darnaComputePrice(labels) {
    var p = darnaParsePriceLabels(labels);
    var num = null, source = null;
    if (p.final !== null && isFinite(parseFloat(p.final))) { num = parseFloat(p.final); source = 'final'; }
    else if (p.base !== null && isFinite(parseFloat(p.base))) { num = parseFloat(p.base) * (1 + DARNA_SERVICE_FEE_RATE); source = 'base'; }
    if (num === null || !isFinite(num)) return null;
    num = Math.round(num * 100) / 100;
    return { amount: num, currency: p.cur, per: p.per, source: source };
  }

  function darnaFormatNumber(n) {
    var s = (n % 1 === 0) ? String(n) : n.toFixed(2);
    var parts = s.split('.');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return parts.join('.');
  }

  function darnaFormatPrice(info, lang) {
    if (!info) return null;
    lang = lang || 'ar';
    var amount = darnaFormatNumber(info.amount);
    var sym = DARNA_CUR_SYMBOL[info.currency] || (info.currency + ' ');
    var unit = '';
    if (info.per) { var map = DARNA_UNITS[lang] || DARNA_UNITS.en; unit = map[info.per] || info.per; }
    return sym + amount + (unit ? ' / ' + unit : '');
  }
  // Expose for testing
  window.darnaParsePriceLabels = darnaParsePriceLabels;
  window.darnaComputePrice = darnaComputePrice;
  window.darnaFormatPrice = darnaFormatPrice;

  /* ================= Small helpers ================= */
  function escapeHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function readStore(key) {
    try { var v = JSON.parse(localStorage.getItem(key) || '[]'); return Array.isArray(v) ? v : []; }
    catch (e) { return []; }
  }
  function writeStore(key, arr) {
    try { localStorage.setItem(key, JSON.stringify(arr)); } catch (e) { /* storage unavailable */ }
  }

  /* ================= Label parsing shared by cards + detail ================= */
  var DARNA_LABEL_RE = /^(pricefinal|price|cur|per|beds|bedrooms|baths|bathrooms|kitchens|kitchen|sqm|area|size|cap|guests|status|availability|type|ptype|loc|location|area_name)\s*[:\-_]\s*(.+)$/i;
  var DARNA_STATUS_WORDS = /^(available|unavailable|occupied|\u0645\u062a\u0648\u0641\u0631|\u0645\u062a\u0648\u0641\u0631\u0629|\u063a\u064a\u0631 \u0645\u062a\u0648\u0641\u0631|\u063a\u064a\u0631 \u0645\u062a\u0648\u0641\u0631\u0629)$/i;

  function darnaReadLabels(scope) {
    var labels = [];
    scope.querySelectorAll('.darna-label').forEach(function (n) {
      var t = (n.textContent || '').replace(/[\u00A0\u200B\uFEFF]/g, '').trim();
      if (t) labels.push(t);
    });
    return labels;
  }

  function darnaParseFields(labels) {
    var f = { price: null, cur: 'USD', per: '', beds: null, baths: null, kitchens: null, sqm: null, cap: null, status: '', type: '', area: '' };
    (labels || []).forEach(function (raw) {
      var t = String(raw).replace(/[\u00A0\u200B\uFEFF]/g, '').trim();
      var m = DARNA_LABEL_RE.exec(t);
      if (m) {
        var k = m[1].toLowerCase(), v = m[2].trim();
        if (k === 'beds' || k === 'bedrooms') f.beds = v;
        else if (k === 'baths' || k === 'bathrooms') f.baths = v;
        else if (k === 'kitchens' || k === 'kitchen') f.kitchens = v;
        else if (k === 'sqm' || k === 'area' || k === 'size') f.sqm = v;
        else if (k === 'cap' || k === 'guests') f.cap = v;
        else if (k === 'status' || k === 'availability') f.status = v;
        else if (k === 'type' || k === 'ptype') f.type = v;
        else if (k === 'loc' || k === 'location' || k === 'area_name') f.area = v;
        return;
      }
      if (DARNA_STATUS_WORDS.test(t)) { if (!f.status) f.status = t; return; }
      // Plain-label fallbacks (Arabic / English property words) — rental product only.
      if (!f.type && /^(\u0634\u0642\u0629|\u0634\u0642\u0629 \u0645\u0641\u0631\u0648\u0634\u0629|\u0641\u064a\u0644\u0627|\u0645\u0646\u0632\u0644|\u0627\u0633\u062a\u0648\u062f\u064a\u0648|\u063a\u0631\u0641\u0629|\u0645\u0641\u0631\u0648\u0634|apartment|villa|house|studio|room)/i.test(t)) f.type = t;
      else if (!f.area && /^[\u0600-\u06FF\s\-]{3,40}$/.test(t) && !/^(\u0639\u0642\u0627\u0631\u0627\u062a|\u0639\u0642\u0627\u0631)$/.test(t)) f.area = t;
    });
    return f;
  }

  function darnaStatusClass(status) {
    var s = darnaNorm(status);
    if (/unavailable|occupied|\u063a\u064a\u0631/.test(s)) return { label: '\u063a\u064a\u0631 \u0645\u062a\u0648\u0641\u0631', cls: 'is-unavailable' };
    if (/available|\u0645\u062a\u0648\u0641\u0631/.test(s)) return { label: '\u0645\u062a\u0648\u0641\u0631', cls: 'is-available' };
    return { label: '\u0627\u0644\u062d\u0627\u0644\u0629 \u063a\u064a\u0631 \u0645\u062d\u062f\u062f\u0629', cls: '' };
  }

  /* ================= Property record (shared by cards, detail, favourites, compare) ================= */
  function darnaRecordFrom(card) {
    var labels = darnaReadLabels(card);
    var f = darnaParseFields(labels);
    var info = darnaComputePrice(labels);
    var img = card.querySelector('.carousel-current-image') || card.querySelector('#gallery-main-img');
    var titleEl = card.querySelector('.card-title') || card.querySelector('.detail-title');
    var title = card.getAttribute('data-title') || (titleEl ? titleEl.textContent.trim() : '');
    return {
      id: card.getAttribute('data-post-id') || card.getAttribute('data-url') || '',
      title: title,
      url: card.getAttribute('data-url') || window.location.href,
      image: (img && img.tagName === 'IMG') ? (img.getAttribute('src') || '') : '',
      price: info ? darnaFormatPrice(info, 'ar') : '',
      priceAmount: info ? info.amount : null,
      unit: info && info.per ? (DARNA_UNITS.ar[info.per] || info.per) : '',
      type: f.type || '',
      area: f.area || '',
      beds: f.beds || '',
      baths: f.baths || '',
      sqm: f.sqm || '',
      status: darnaStatusClass(f.status).label
    };
  }

  /* ================= Card rendering ================= */
  function darnaRenderCard(card) {
    var labels = darnaReadLabels(card);
    var f = darnaParseFields(labels);
    var info = darnaComputePrice(labels);

    // price (prominent, USD, thousands separator, unit)
    var priceEl = card.querySelector('[data-darna-price] .darna-price-value');
    if (priceEl) {
      priceEl.textContent = info ? darnaFormatPrice(info, 'ar') : '';
      var wrap = card.querySelector('.card-price');
      if (wrap) wrap.setAttribute('data-price-value', info ? String(info.amount) : '');
    }

    // features: beds / baths / area (sqm)
    function setVal(sel, v) { var e = card.querySelector(sel); if (e) e.textContent = (v == null || v === '') ? '\u2014' : v; }
    setVal('[data-value="beds"]', f.beds);
    setVal('[data-value="baths"]', f.baths);
    setVal('[data-value="sqm"]', f.sqm);

    // city / area
    var areaEl = card.querySelector('.card-area');
    if (areaEl) areaEl.textContent = f.area || '';
    var locWrap = card.querySelector('.card-loc');
    if (locWrap && !f.area) locWrap.hidden = true;

    // type chip (separate from availability)
    var typeChip = card.querySelector('.card-type');
    if (typeChip) {
      if (f.type) { typeChip.textContent = f.type; typeChip.hidden = false; }
      else { typeChip.hidden = true; }
    }

    // availability badge (separate from type)
    var st = darnaStatusClass(f.status);
    var badge = card.querySelector('.feature-status');
    if (badge) {
      badge.textContent = st.label;
      badge.classList.remove('is-available', 'is-unavailable');
      if (st.cls) badge.classList.add(st.cls);
    }

    // short description (1-2 lines)
    var srcEl = card.querySelector('.carousel-post-images');
    var bodyText = srcEl ? (srcEl.tagName === 'TEXTAREA' ? srcEl.value : srcEl.textContent) : '';
    bodyText = bodyText.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    var descEl = card.querySelector('.card-desc');
    if (descEl) {
      if (bodyText) { descEl.textContent = bodyText.slice(0, 110) + (bodyText.length > 110 ? '\u2026' : ''); }
      else { descEl.hidden = true; }
    }

    // data attributes for LOCAL filtering
    card.setAttribute('data-type', f.type || '');
    card.setAttribute('data-area', f.area || '');
    var statusNorm = darnaNorm(f.status);
    card.setAttribute('data-status', /unavailable|\u063a\u064a\u0631/.test(statusNorm) ? 'unavailable' : (/available|\u0645\u062a\u0648\u0641\u0631/.test(statusNorm) ? 'available' : ''));
    card.setAttribute('data-beds', f.beds != null ? String(parseInt(f.beds, 10) || 0) : '');
    card.setAttribute('data-baths', f.baths != null ? String(parseInt(f.baths, 10) || 0) : '');
    card.setAttribute('data-sqm', f.sqm != null ? String(parseFloat(f.sqm) || 0) : '');
    card.setAttribute('data-unit', info && info.per ? info.per : '');
    card.setAttribute('data-price', info ? String(info.amount) : '');
    card.setAttribute('data-search', darnaNorm((card.getAttribute('data-title') || '') + ' ' + bodyText + ' ' + labels.join(' ')));
  }

  /* ================= Card photo carousel (one click = one image) ================= */
  function darnaCarousel(box) {
    if (box.getAttribute('data-carousel-init') === '1') return;
    box.setAttribute('data-carousel-init', '1');
    var img = box.querySelector('.carousel-current-image');
    var prev = box.querySelector('.photo-prev'), next = box.querySelector('.photo-next');
    var count = box.querySelector('.photo-counter');
    var source = box.querySelector('.carousel-post-images');
    var link = box.querySelector('.property-photo-link');
    if (!prev || !next) return;

    var urls = [];
    function add(u) {
      if (!u) return;
      u = String(u).replace(/&amp;/g, '&');
      if (/^data:/i.test(u) || /transparent\.gif/i.test(u) || /sprite/i.test(u)) return;
      if (urls.indexOf(u) < 0) urls.push(u);
    }
    if (img && img.tagName === 'IMG') add(img.getAttribute('src'));
    if (source) {
      if (source.tagName === 'TEXTAREA') {
        var re = /<img[^>]+src=["']([^"']+)["']/gi, mm;
        while ((mm = re.exec(source.value || ''))) add(mm[1]);
      } else {
        source.querySelectorAll('img').forEach(function (i) {
          add(i.getAttribute('src') || i.getAttribute('data-src') || i.getAttribute('data-original'));
        });
      }
    }

    if (!urls.length) {
      prev.hidden = next.hidden = true;
      if (count) count.hidden = true;
      box.setAttribute('data-image-count', '0');
      return;
    }

    var index = 0;
    function show(i) {
      index = (i + urls.length) % urls.length;
      if (img && img.tagName === 'IMG') {
        img.classList.remove('is-broken');
        img.setAttribute('src', urls[index]);
      }
      if (count) count.textContent = (index + 1) + '/' + urls.length;
      box.setAttribute('data-image-count', String(urls.length));
      var multi = urls.length > 1;
      prev.disabled = next.disabled = !multi;
      prev.hidden = next.hidden = !multi;
      if (count) count.hidden = !multi;
    }
    function go(delta) { show(index + delta); }

    // Buttons: exactly one transition per click. Never suppressed by the swipe guard.
    prev.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); go(-1); });
    next.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); go(1); });

    // Broken image handling
    if (img && img.tagName === 'IMG') {
      img.addEventListener('error', function () {
        img.classList.add('is-broken');
        img.setAttribute('alt', '\u062a\u0639\u0630\u0651\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0635\u0648\u0631\u0629');
      });
    }

    // Keyboard support (arrow keys) when the carousel is focused
    box.setAttribute('tabindex', '0');
    box.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowRight') { go(1); }
      else if (e.key === 'ArrowLeft') { go(-1); }
    });

    // Touch / drag swipe via Pointer Events. Only the LINK click is suppressed after a swipe.
    var startX = 0, startY = 0, moved = false, suppressLink = false;
    box.addEventListener('pointerdown', function (e) {
      if (e.target.closest('button')) return;
      startX = e.clientX; startY = e.clientY; moved = false; suppressLink = false;
    }, { passive: true });
    box.addEventListener('pointermove', function (e) {
      if (e.target.closest('button')) return;
      if (Math.abs(e.clientX - startX) > 8) moved = true;
    }, { passive: true });
    box.addEventListener('pointerup', function (e) {
      if (e.target.closest('button')) return;
      var dx = e.clientX - startX, dy = e.clientY - startY;
      if (urls.length > 1 && moved && Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy) * 1.25) {
        suppressLink = true;
        go(dx < 0 ? 1 : -1);
      }
    }, { passive: true });
    if (link) {
      link.addEventListener('click', function (e) {
        if (suppressLink) { e.preventDefault(); e.stopPropagation(); suppressLink = false; }
      });
    }

    show(0);
  }

  /* ================= Detail page ================= */
  function darnaRenderDetail() {
    var art = document.querySelector('.property-detail');
    if (!art) return;
    var labels = darnaReadLabels(art);
    var f = darnaParseFields(labels);
    var info = darnaComputePrice(labels);

    var priceEl = art.querySelector('[data-darna-price] .darna-price-value');
    if (priceEl) priceEl.textContent = info ? darnaFormatPrice(info, 'ar') : '';

    var st = darnaStatusClass(f.status);
    var badge = art.querySelector('.detail-status');
    if (badge) {
      badge.textContent = st.label;
      badge.classList.remove('is-available', 'is-unavailable');
      if (st.cls) badge.classList.add(st.cls);
    }

    // type chip (separate from availability)
    var typeChip = art.querySelector('.detail-type');
    if (typeChip) {
      if (f.type) { typeChip.textContent = f.type; typeChip.hidden = false; }
      else { typeChip.hidden = true; }
    }

    // specs
    var specs = art.querySelector('#detail-specs');
    if (specs) {
      var items = [];
      if (f.beds) items.push(['\uD83D\uDECF', f.beds, '\u063a\u0631\u0641 \u0627\u0644\u0646\u0648\u0645']);
      if (f.baths) items.push(['\uD83D\uDEBF', f.baths, '\u0627\u0644\u062d\u0645\u0627\u0645\u0627\u062a']);
      if (f.sqm) items.push(['\uD83D\uDCD0', f.sqm + ' \u0645\u00B2', '\u0627\u0644\u0645\u0633\u0627\u062d\u0629']);
      if (f.cap) items.push(['\uD83D\uDC65', f.cap, '\u0627\u0644\u0633\u0639\u0629']);
      if (f.type) items.push(['\uD83C\uDFE0', f.type, '\u0627\u0644\u0646\u0648\u0639']);
      if (f.area) items.push(['\uD83D\uDCCD', f.area, '\u0627\u0644\u0645\u0646\u0637\u0642\u0629']);
      specs.innerHTML = items.map(function (it) {
        return '<div class="spec-item"><span class="spec-icon" aria-hidden="true">' + it[0] + '</span><span class="spec-value">' + escapeHtml(it[1]) + '</span><span class="spec-label">' + it[2] + '</span></div>';
      }).join('');
      if (!items.length) specs.style.display = 'none';
    }

    // gallery from featured image + body images
    var main = art.querySelector('#gallery-main-img');
    var thumbs = art.querySelector('#gallery-thumbs');
    var counter = art.querySelector('#gallery-counter');
    var bodyImgs = art.querySelectorAll('#detail-body img');
    var urls = [];
    function add(u) { if (!u) return; u = String(u).replace(/&amp;/g, '&'); if (/^data:/i.test(u) || /transparent\.gif/i.test(u)) return; if (urls.indexOf(u) < 0) urls.push(u); }
    if (main && main.getAttribute('src')) add(main.getAttribute('src'));
    bodyImgs.forEach(function (i) { add(i.getAttribute('src') || i.getAttribute('data-src')); i.style.display = 'none'; });
    var idx = 0;
    function showDetail(i) {
      if (!urls.length) return;
      idx = (i + urls.length) % urls.length;
      if (main && main.tagName === 'IMG') main.setAttribute('src', urls[idx]);
      if (counter) counter.textContent = (idx + 1) + '/' + urls.length;
      if (thumbs) Array.prototype.forEach.call(thumbs.children, function (t, k) { t.classList.toggle('active', k === idx); });
      var multi = urls.length > 1;
      var pb = art.querySelector('.gallery-btn.prev'), nb = art.querySelector('.gallery-btn.next');
      if (pb) pb.hidden = !multi;
      if (nb) nb.hidden = !multi;
      if (counter) counter.hidden = !multi;
    }
    if (thumbs) {
      thumbs.innerHTML = '';
      urls.forEach(function (u, i) {
        var t = document.createElement('img');
        t.className = 'gallery-thumb' + (i === 0 ? ' active' : '');
        t.src = u; t.alt = '\u0635\u0648\u0631\u0629 ' + (i + 1);
        t.setAttribute('role', 'button'); t.setAttribute('tabindex', '0');
        t.addEventListener('click', function () { showDetail(i); });
        t.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); showDetail(i); } });
        thumbs.appendChild(t);
      });
    }
    var pb = art.querySelector('.gallery-btn.prev'), nb = art.querySelector('.gallery-btn.next');
    if (pb) pb.addEventListener('click', function () { showDetail(idx - 1); });
    if (nb) nb.addEventListener('click', function () { showDetail(idx + 1); });
    var gmain = art.querySelector('#gallery-main');
    if (gmain) {
      var sx = 0, moved = false;
      gmain.addEventListener('pointerdown', function (e) { if (!e.target.closest('button')) { sx = e.clientX; moved = false; } }, { passive: true });
      gmain.addEventListener('pointermove', function (e) { if (Math.abs(e.clientX - sx) > 8) moved = true; }, { passive: true });
      gmain.addEventListener('pointerup', function (e) {
        if (e.target.closest('button')) return;
        var dx = e.clientX - sx;
        if (urls.length > 1 && moved && Math.abs(dx) > 45) showDetail(idx + (dx < 0 ? 1 : -1));
      }, { passive: true });
    }
    showDetail(0);

    darnaLoadSimilar(art, labels);
  }

  function darnaLoadSimilar(art, labels) {
    var section = art.querySelector('#similar-section');
    var grid = art.querySelector('#similar-grid');
    if (!section || !grid) return;
    var skip = /^(price|pricefinal|cur|per|beds|bedrooms|baths|bathrooms|kitchens|kitchen|sqm|area|size|cap|guests|status|availability|type|ptype|loc|location)\s*[:\-_]/i;
    var label = null;
    for (var i = 0; i < labels.length; i++) { if (!skip.test(labels[i])) { label = labels[i]; break; } }
    if (!label) return;
    var base = (window.location.origin || '') + '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=5';
    fetch(base).then(function (r) { return r.json(); }).then(function (data) {
      var entries = (data && data.feed && data.feed.entry) || [];
      var current = window.location.href;
      var shown = 0;
      entries.forEach(function (e) {
        var link = '';
        (e.link || []).forEach(function (l) { if (l.rel === 'alternate') link = l.href; });
        if (!link || link === current) return;
        var title = e.title && e.title.$t ? e.title.$t : '';
        var img = '';
        try {
          if (e.media$thumbnail && e.media$thumbnail.url) {
            img = e.media$thumbnail.url.replace(/\/s72-c\//, '/w600-h450-c/');
          } else if (e.content && e.content.$t) {
            var mm = e.content.$t.match(/<img[^>]+(?:src|data-src)=["']([^"']+)["']/i);
            if (mm && mm[1]) img = mm[1].replace(/^http:/, 'https:');
          }
        } catch (err) { img = ''; }
        img = img ? escapeHtml(img) : '';
        var card = document.createElement('article');
        card.className = 'property-card';
        card.setAttribute('data-url', link);
        card.setAttribute('data-title', title);
        card.innerHTML =
          '<div class="property-photo-carousel" data-image-count="1">' +
          '<a class="property-photo-link" href="' + link + '" aria-label="' + escapeHtml(title) + '">' +
          (img ? '<img class="card-image carousel-current-image" src="' + img + '" alt="' + escapeHtml(title) + '" loading="lazy"/>' : '<div class="card-image carousel-empty">\u0644\u0627 \u062a\u0648\u062c\u062f \u0635\u0648\u0631\u0629</div>') +
          '</a></div>' +
          '<div class="card-body"><h3 class="card-title"><a href="' + link + '">' + escapeHtml(title) + '</a></h3>' +
          '<a class="card-link" href="' + link + '">\u0639\u0631\u0636 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644</a></div>';
        grid.appendChild(card);
        shown++;
      });
      if (shown) section.hidden = false;
    }).catch(function () { /* graceful: leave hidden */ });
  }

  /* ================= Inquiry form ================= */
  function darnaInitInquiry() {
    var form = document.getElementById('inquiry-form');
    if (!form) return;
    var nameEl = document.getElementById('inq-name');
    var phoneEl = document.getElementById('inq-phone');
    function setErr(fieldId, errId, msg) {
      var fld = document.getElementById(fieldId), err = document.getElementById(errId);
      if (fld) fld.classList.toggle('invalid', !!msg);
      if (err) err.textContent = msg || '';
    }
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (form.getAttribute('data-sending') === '1') return;
      var ok = true;
      var name = (nameEl.value || '').trim();
      var phone = (phoneEl.value || '').trim();
      if (name.length < 2) { setErr('fld-name', 'err-name', '\u064a\u0631\u062c\u0649 \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0627\u0633\u0645.'); ok = false; } else setErr('fld-name', 'err-name', '');
      if (!/^[+0-9\s\-()]{6,}$/.test(phone)) { setErr('fld-phone', 'err-phone', '\u064a\u0631\u062c\u0649 \u0625\u062f\u062e\u0627\u0644 \u0631\u0642\u0645 \u0647\u0627\u062a\u0641 \u0635\u062d\u064a\u062d.'); ok = false; } else setErr('fld-phone', 'err-phone', '');
      if (!ok) { var bad = form.querySelector('.invalid input'); if (bad) bad.focus(); return; }
      var prop = document.getElementById('inq-property').value || '';
      var url = document.getElementById('inq-url').value || window.location.href;
      var type = document.getElementById('inq-type').value || '\u0627\u0633\u062a\u0641\u0633\u0627\u0631';
      var checkin = document.getElementById('inq-checkin').value || '';
      var checkout = document.getElementById('inq-checkout').value || '';
      var guests = document.getElementById('inq-guests').value || '';
      var msg = (document.getElementById('inq-msg').value || '').trim();
      var lines = [
        '\u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0643\u0645\u060c \u0623\u0631\u063a\u0628 \u0628\u0627\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631 \u0639\u0628\u0631 Place-dj.',
        '\u0627\u0644\u0639\u0642\u0627\u0631: ' + prop,
        '\u0646\u0648\u0639 \u0627\u0644\u0637\u0644\u0628: ' + type,
        '\u0627\u0644\u0627\u0633\u0645: ' + name,
        '\u0627\u0644\u0647\u0627\u062a\u0641: ' + phone
      ];
      if (checkin) lines.push('\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0648\u0635\u0648\u0644: ' + checkin);
      if (checkout) lines.push('\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u063a\u0627\u062f\u0631\u0629: ' + checkout);
      if (guests) lines.push('\u0639\u062f\u062f \u0627\u0644\u0623\u0634\u062e\u0627\u0635: ' + guests);
      if (msg) lines.push('\u0627\u0644\u0631\u0633\u0627\u0644\u0629: ' + msg);
      lines.push('\u0631\u0627\u0628\u0637 \u0627\u0644\u0639\u0642\u0627\u0631: ' + url);
      var wa = 'https://wa.me/25377313443?text=' + encodeURIComponent(lines.join('\n'));
      form.setAttribute('data-sending', '1');
      window.open(wa, '_blank', 'noopener');
      var success = document.getElementById('inq-success');
      if (success) { success.hidden = false; success.textContent = '\u062a\u0645 \u0641\u062a\u062d \u0648\u0627\u062a\u0633\u0627\u0628 \u0628\u0631\u0633\u0627\u0644\u062a\u0643. \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0644\u0627 \u064a\u0624\u0643\u062f \u0627\u0644\u062d\u062c\u0632 \u2014 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u062a\u0624\u0643\u062f \u0627\u0644\u062a\u0648\u0641\u0631 \u0648\u0627\u0644\u0633\u0639\u0631 \u0643\u062a\u0627\u0628\u064a\u064b\u0627.'; }
      setTimeout(function () { form.removeAttribute('data-sending'); }, 1500);
    });
  }

  /* ================= Local filters (loaded cards only) ================= */
  function darnaInitFilters() {
    var panel = document.getElementById('darna-filters');
    var grid = document.getElementById('property-grid');
    if (!panel || !grid || panel.getAttribute('data-filter-init') === '1') return;
    var cards = Array.prototype.slice.call(grid.querySelectorAll('.property-card'));
    if (!cards.length) {
      var empty = panel.querySelector('.filters-status');
      if (empty) empty.textContent = 'لا توجد بطاقات محمّلة لتصفيتها في هذه الصفحة.';
      return;
    }
    panel.setAttribute('data-filter-init', '1');
    var qEl = document.getElementById('f-q'), typeEl = document.getElementById('f-type'), areaEl = document.getElementById('f-area');
    var statusEl = document.getElementById('f-status'), unitEl = document.getElementById('f-unit');
    var minEl = document.getElementById('f-min'), maxEl = document.getElementById('f-max');
    var bedsEl = document.getElementById('f-beds'), bathsEl = document.getElementById('f-baths');
    var sqmEl = document.getElementById('f-sqm'), sortEl = document.getElementById('f-sort');
    var countEl = document.getElementById('f-count'), resetEl = document.getElementById('f-reset');
    var types = {}, areas = {}, units = {};
    cards.forEach(function (c) {
      var t = c.getAttribute('data-type') || '', a = c.getAttribute('data-area') || '', u = c.getAttribute('data-unit') || '';
      if (t) types[t] = 1; if (a) areas[a] = 1; if (u) units[u] = 1;
    });
    function fill(sel, obj) {
      if (!sel) return;
      Object.keys(obj).sort().forEach(function (v) {
        if (!Array.prototype.some.call(sel.options, function (o) { return o.value === v; })) {
          var o = document.createElement('option'); o.value = v; o.textContent = v; sel.appendChild(o);
        }
      });
    }
    fill(typeEl, types); fill(areaEl, areas); fill(unitEl, units);
    var originalOrder = cards.slice();
    var noResults = document.createElement('div');
    noResults.className = 'no-results filter-no-results';
    noResults.hidden = true;
    noResults.innerHTML = '<p>لا توجد عقارات مطابقة للخيارات المحددة.</p><p style="font-size:.85rem;margin-top:8px;">جرّب تغيير الفلاتر أو إعادة ضبطها.</p>';
    grid.parentNode.insertBefore(noResults, grid.nextSibling);
    function number(v) { var n = parseFloat(v); return isFinite(n) ? n : null; }
    function apply() {
      var q = darnaNorm(qEl ? qEl.value : '');
      var type = typeEl ? typeEl.value : '', area = areaEl ? areaEl.value : '';
      var status = statusEl ? statusEl.value : '', unit = unitEl ? unitEl.value : '';
      var min = minEl && minEl.value !== '' ? number(minEl.value) : null;
      var max = maxEl && maxEl.value !== '' ? number(maxEl.value) : null;
      var beds = bedsEl && bedsEl.value ? parseInt(bedsEl.value, 10) : null;
      var baths = bathsEl && bathsEl.value ? parseInt(bathsEl.value, 10) : null;
      var sqm = sqmEl && sqmEl.value !== '' ? number(sqmEl.value) : null;
      var visible = 0;
      cards.forEach(function (c) {
        var price = number(c.getAttribute('data-price')), cbeds = number(c.getAttribute('data-beds'));
        var cbaths = number(c.getAttribute('data-baths')), csqm = number(c.getAttribute('data-sqm'));
        var text = darnaNorm(c.getAttribute('data-search') || c.getAttribute('data-title') || '');
        var ok = (!q || text.indexOf(q) !== -1) && (!type || c.getAttribute('data-type') === type) && (!area || c.getAttribute('data-area') === area) && (!status || c.getAttribute('data-status') === status) && (!unit || c.getAttribute('data-unit') === unit) && (min === null || (price !== null && price >= min)) && (max === null || (price !== null && price <= max)) && (beds === null || (cbeds !== null && cbeds >= beds)) && (baths === null || (cbaths !== null && cbaths >= baths)) && (sqm === null || (csqm !== null && csqm >= sqm));
        c.hidden = !ok;
        if (ok) visible++;
      });
      var sort = sortEl ? sortEl.value : 'default';
      var ordered = originalOrder.slice();
      if (sort === 'price-asc') ordered.sort(function (a,b) { return (number(a.getAttribute('data-price')) === null ? Infinity : number(a.getAttribute('data-price'))) - (number(b.getAttribute('data-price')) === null ? Infinity : number(b.getAttribute('data-price'))); });
      else if (sort === 'price-desc') ordered.sort(function (a,b) { return (number(b.getAttribute('data-price')) === null ? -Infinity : number(b.getAttribute('data-price'))) - (number(a.getAttribute('data-price')) === null ? -Infinity : number(a.getAttribute('data-price'))); });
      else if (sort === 'beds-desc') ordered.sort(function (a,b) { return (number(b.getAttribute('data-beds')) || 0) - (number(a.getAttribute('data-beds')) || 0); });
      else if (sort === 'sqm-desc') ordered.sort(function (a,b) { return (number(b.getAttribute('data-sqm')) || 0) - (number(a.getAttribute('data-sqm')) || 0); });
      ordered.forEach(function (c) { grid.appendChild(c); });
      noResults.hidden = visible !== 0;
      grid.hidden = visible === 0;
      if (countEl) countEl.innerHTML = 'عدد النتائج المعروضة: <strong>' + visible + '</strong>';
    }
    function debounce(fn, wait) { var timer; return function () { clearTimeout(timer); timer = setTimeout(fn, wait); }; }
    [qEl, minEl, maxEl, sqmEl].forEach(function (el) { if (el) { el.addEventListener('input', debounce(apply, 180)); el.addEventListener('change', apply); } });
    [typeEl, areaEl, statusEl, unitEl, bedsEl, bathsEl, sortEl].forEach(function (el) { if (el) el.addEventListener('change', apply); });
    var applyBtn = document.getElementById('f-apply');
    if (applyBtn) applyBtn.addEventListener('click', function () { apply(); var d = document.getElementById('filters-disclosure'); if (d && window.innerWidth < 769) d.open = false; });
    if (resetEl) resetEl.addEventListener('click', function () { [qEl,typeEl,areaEl,statusEl,unitEl,minEl,maxEl,bedsEl,bathsEl,sqmEl].forEach(function (el) { if (el) el.value = ''; }); if (sortEl) sortEl.value = 'default'; apply(); });
    window.darnaApplyFilters = apply;
    apply();
  }

  /* ================= Favourites ================= */
  var FAV_KEY = 'placedj_favorites_v1';
  function favList() { return readStore(FAV_KEY); }
  function isFav(id) { return favList().some(function (r) { return r.id === id; }); }
  function toggleFav(rec) {
    if (!rec || !rec.id) return false;
    var list = favList();
    var i = -1;
    list.forEach(function (r, k) { if (r.id === rec.id) i = k; });
    if (i >= 0) list.splice(i, 1); else list.unshift(rec);
    writeStore(FAV_KEY, list);
    syncFavButtons(); renderFavPanel();
    return i < 0;
  }
  function removeFav(id) {
    writeStore(FAV_KEY, favList().filter(function (r) { return r.id !== id; }));
    syncFavButtons(); renderFavPanel();
  }
  function syncFavButtons() {
    document.querySelectorAll('.card-fav').forEach(function (btn) {
      var card = btn.closest('.property-card');
      var id = card ? (card.getAttribute('data-post-id') || card.getAttribute('data-url')) : '';
      var on = isFav(id);
      btn.classList.toggle('is-active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      btn.setAttribute('aria-label', on ? '\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629' : '\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0641\u0636\u0644\u0629');
    });
    var dt = document.querySelector('.detail-fav');
    if (dt) {
      var art = document.querySelector('.property-detail');
      var id2 = art ? (art.getAttribute('data-post-id') || '') : '';
      var on2 = isFav(id2);
      dt.classList.toggle('is-active', on2);
      dt.setAttribute('aria-pressed', on2 ? 'true' : 'false');
      dt.setAttribute('aria-label', on2 ? '\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629' : '\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0641\u0636\u0644\u0629');
    }
  }
  function renderFavPanel() {
    var listEl = document.getElementById('favorites-list');
    var list = favList();
    var toggle = document.getElementById('favorites-toggle');
    if (toggle) { toggle.setAttribute('data-count', String(list.length)); var b = toggle.querySelector('.fav-badge'); if (b) b.textContent = String(list.length); }
    if (!listEl) return;
    if (!list.length) {
      listEl.innerHTML = '<p class="fav-empty">\u0644\u0627 \u062a\u0648\u062c\u062f \u0639\u0642\u0627\u0631\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0628\u0639\u062f. \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0642\u0644\u0628 \u0641\u064a \u0623\u064a \u0628\u0637\u0627\u0642\u0629 \u0644\u0625\u0636\u0627\u0641\u062a\u0647\u0627.</p>';
      return;
    }
    listEl.innerHTML = list.map(function (r) {
      return '<article class="fav-item">' +
        '<a class="fav-thumb" href="' + r.url + '">' + (r.image ? '<img src="' + r.image + '" alt="" loading="lazy"/>' : '<span class="fav-noimg">\u0644\u0627 \u0635\u0648\u0631\u0629</span>') + '</a>' +
        '<div class="fav-info"><a class="fav-title" href="' + r.url + '">' + escapeHtml(r.title) + '</a>' +
        '<div class="fav-meta">' + escapeHtml([r.type, r.area].filter(Boolean).join(' \u00B7 ')) + '</div>' +
        '<div class="fav-price">' + escapeHtml(r.price || '') + '</div></div>' +
        '<button type="button" class="fav-remove" data-id="' + escapeHtml(r.id) + '" aria-label="\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629">\u00D7</button>' +
        '</article>';
    }).join('');
    listEl.querySelectorAll('.fav-remove').forEach(function (b) {
      b.addEventListener('click', function () { removeFav(b.getAttribute('data-id')); });
    });
  }
  function darnaInitFavorites() {
    document.querySelectorAll('.property-card .card-fav').forEach(function (btn) {
      if (btn.getAttribute('data-fav-init') === '1') return;
      btn.setAttribute('data-fav-init', '1');
      btn.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        var card = btn.closest('.property-card');
        if (card) toggleFav(darnaRecordFrom(card));
      });
    });
    var dt = document.querySelector('.detail-fav');
    if (dt && dt.getAttribute('data-fav-init') !== '1') {
      dt.setAttribute('data-fav-init', '1');
      dt.addEventListener('click', function (e) {
        e.preventDefault();
        var art = document.querySelector('.property-detail');
        if (art) toggleFav(darnaRecordFrom(art));
      });
    }
    var toggle = document.getElementById('favorites-toggle');
    var panel = document.getElementById('favorites-panel');
    if (toggle && panel) {
      toggle.addEventListener('click', function () {
        panel.hidden = !panel.hidden;
        toggle.setAttribute('aria-expanded', panel.hidden ? 'false' : 'true');
      });
    }
    var close = document.getElementById('favorites-close');
    if (close && panel) close.addEventListener('click', function () { panel.hidden = true; });
    syncFavButtons();
    renderFavPanel();
  }

  /* ================= Comparison ================= */
  var CMP_KEY = 'placedj_compare_v1';
  var CMP_MAX = 4;
  function cmpList() { return readStore(CMP_KEY); }
  function isCmp(id) { return cmpList().some(function (r) { return r.id === id; }); }
  function toggleCmp(rec) {
    if (!rec || !rec.id) return false;
    var list = cmpList();
    var i = -1;
    list.forEach(function (r, k) { if (r.id === rec.id) i = k; });
    if (i >= 0) list.splice(i, 1);
    else { if (list.length >= CMP_MAX) { window.alert('\u064a\u0645\u0643\u0646 \u0645\u0642\u0627\u0631\u0646\u0629 ' + CMP_MAX + ' \u0639\u0642\u0627\u0631\u0627\u062a \u0643\u062d\u062f \u0623\u0642\u0635\u0649.'); return false; } list.push(rec); }
    writeStore(CMP_KEY, list);
    syncCmpButtons(); renderCompareBar(); renderCompareTable();
    return i < 0;
  }
  function removeCmp(id) {
    writeStore(CMP_KEY, cmpList().filter(function (r) { return r.id !== id; }));
    syncCmpButtons(); renderCompareBar(); renderCompareTable();
  }
  function syncCmpButtons() {
    document.querySelectorAll('.card-compare').forEach(function (btn) {
      var card = btn.closest('.property-card');
      var id = card ? (card.getAttribute('data-post-id') || card.getAttribute('data-url')) : '';
      var on = isCmp(id);
      btn.classList.toggle('is-active', on);
      btn.setAttribute('aria-pressed', on ? 'true' : 'false');
      btn.setAttribute('aria-label', on ? '\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629' : '\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629');
    });
    var dc = document.querySelector('.detail-compare');
    if (dc) {
      var art = document.querySelector('.property-detail');
      var id2 = art ? (art.getAttribute('data-post-id') || '') : '';
      var on2 = isCmp(id2);
      dc.classList.toggle('is-active', on2);
      dc.setAttribute('aria-pressed', on2 ? 'true' : 'false');
    }
  }
  function renderCompareBar() {
    var bar = document.getElementById('compare-bar');
    var items = document.getElementById('compare-items');
    if (!bar) return;
    var list = cmpList();
    bar.hidden = !list.length;
    if (items) items.textContent = '\u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629 (' + list.length + '/' + CMP_MAX + ')';
  }
  function renderCompareTable() {
    var wrap = document.getElementById('compare-table');
    if (!wrap) return;
    var list = cmpList();
    if (!list.length) { wrap.innerHTML = '<p class="compare-empty">\u0644\u0645 \u062a\u064f\u0636\u0641 \u0623\u064a \u0639\u0642\u0627\u0631\u0627\u062a \u0644\u0644\u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0639\u062f.</p>'; return; }
    var rows = [
      ['\u0627\u0644\u0633\u0639\u0631', 'price'],
      ['\u0648\u062d\u062f\u0629 \u0627\u0644\u0633\u0639\u0631', 'unit'],
      ['\u0627\u0644\u0646\u0648\u0639', 'type'],
      ['\u0627\u0644\u0645\u0646\u0637\u0642\u0629', 'area'],
      ['\u0627\u0644\u0645\u0633\u0627\u062d\u0629 (\u0645\u00B2)', 'sqm'],
      ['\u063a\u0631\u0641 \u0627\u0644\u0646\u0648\u0645', 'beds'],
      ['\u0627\u0644\u062d\u0645\u0627\u0645\u0627\u062a', 'baths'],
      ['\u0627\u0644\u062a\u0648\u0641\u0631', 'status']
    ];
    var html = '<table class="compare-table"><thead><tr><th scope="col">\u0627\u0644\u062e\u0627\u0635\u064a\u0629</th>';
    list.forEach(function (r) {
      html += '<th scope="col"><div class="cmp-head">' + (r.image ? '<img src="' + r.image + '" alt="" loading="lazy"/>' : '') +
        '<a href="' + r.url + '">' + escapeHtml(r.title) + '</a>' +
        '<button type="button" class="cmp-remove" data-id="' + escapeHtml(r.id) + '" aria-label="\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0642\u0627\u0631\u0646\u0629">\u00D7</button></div></th>';
    });
    html += '</tr></thead><tbody>';
    rows.forEach(function (row) {
      html += '<tr><th scope="row">' + row[0] + '</th>';
      list.forEach(function (r) {
        var v = r[row[1]];
        html += '<td>' + (v != null && v !== '' ? escapeHtml(String(v)) : '<span class="cmp-na">\u063a\u064a\u0631 \u0645\u062a\u0648\u0641\u0631</span>') + '</td>';
      });
      html += '</tr>';
    });
    html += '</tbody></table>';
    wrap.innerHTML = html;
    wrap.querySelectorAll('.cmp-remove').forEach(function (b) {
      b.addEventListener('click', function () { removeCmp(b.getAttribute('data-id')); });
    });
  }
  function darnaInitCompare() {
    document.querySelectorAll('.property-card .card-compare').forEach(function (btn) {
      if (btn.getAttribute('data-cmp-init') === '1') return;
      btn.setAttribute('data-cmp-init', '1');
      btn.addEventListener('click', function (e) {
        e.preventDefault(); e.stopPropagation();
        var card = btn.closest('.property-card');
        if (card) toggleCmp(darnaRecordFrom(card));
      });
    });
    var dc = document.querySelector('.detail-compare');
    if (dc && dc.getAttribute('data-cmp-init') !== '1') {
      dc.setAttribute('data-cmp-init', '1');
      dc.addEventListener('click', function (e) {
        e.preventDefault();
        var art = document.querySelector('.property-detail');
        if (art) toggleCmp(darnaRecordFrom(art));
      });
    }
    var open = document.getElementById('compare-open');
    var modal = document.getElementById('compare-modal');
    if (open && modal) open.addEventListener('click', function () { renderCompareTable(); modal.hidden = false; });
    var close = document.getElementById('compare-close');
    if (close && modal) close.addEventListener('click', function () { modal.hidden = true; });
    var clear = document.getElementById('compare-clear');
    if (clear) clear.addEventListener('click', function () { writeStore(CMP_KEY, []); syncCmpButtons(); renderCompareBar(); renderCompareTable(); });
    syncCmpButtons(); renderCompareBar();
  }

  /* ================= Search submission ================= */
  function darnaSubmitSearch(form) {
    var field = form && form.querySelector('input[name="q"]');
    if (!field) return false;
    var value = String(field.value || '').replace(/\s+/g, ' ').trim();
    if (!value) { field.value = ''; field.focus(); return false; }
    field.value = value;
    return true;
  }

  /* ================= Language selector (configurable) ================= */
  var LANG_KEY = 'placedj_lang_v1';
  var PLACEDJ_LANGS = { ar: 'https://www.place-dj.com', en: 'https://en.place-dj.com', fr: 'https://fr.place-dj.com' };
  function darnaInitLang() {
    var links = document.querySelectorAll('.lang-link[data-lang]');
    if (!links.length) return;
    Array.prototype.forEach.call(links, function (link) {
      link.addEventListener('click', function () {
        try { localStorage.setItem(LANG_KEY, link.getAttribute('data-lang')); } catch (e) { }
      });
    });
  }


  /* ================= Lightweight Hero slider ================= */
  function darnaInitHeroSlider() {
    var root = document.getElementById('hero-slider');
    if (!root) return;
    var slides = Array.prototype.slice.call(root.querySelectorAll('.hero-slide'));
    var dots = root.querySelector('.hero-slider-dots');
    if (!slides.length) { root.hidden = true; return; }
    if (root.getAttribute('data-slider-init') === '1') return;
    root.setAttribute('data-slider-init', '1');
    var index = 0, timer = null, startX = 0, moved = false;
    function show(n) {
      index = (n + slides.length) % slides.length;
      slides.forEach(function (slide, i) { slide.classList.toggle('is-active', i === index); });
      if (dots) Array.prototype.forEach.call(dots.children, function (dot, i) { dot.classList.toggle('is-active', i === index); dot.setAttribute('aria-selected', i === index ? 'true' : 'false'); });
    }
    function stop() { if (timer) { clearInterval(timer); timer = null; } }
    function start() { stop(); if (slides.length > 1 && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) timer = setInterval(function () { show(index + 1); }, 3000); }
    if (dots) slides.forEach(function (_, i) { var dot = document.createElement('button'); dot.type='button'; dot.className='hero-slider-dot'; dot.setAttribute('role','tab'); dot.setAttribute('aria-label','الصورة ' + (i+1)); dot.addEventListener('click', function () { show(i); start(); }); dots.appendChild(dot); });
    root.addEventListener('mouseenter', stop); root.addEventListener('mouseleave', start); root.addEventListener('focusin', stop); root.addEventListener('focusout', start);
    root.addEventListener('pointerdown', function (e) { startX=e.clientX; moved=false; }, {passive:true});
    root.addEventListener('pointermove', function (e) { if (Math.abs(e.clientX-startX)>10) moved=true; }, {passive:true});
    root.addEventListener('pointerup', function (e) { var dx=e.clientX-startX; if (moved && Math.abs(dx)>45) { show(index+(dx<0?1:-1)); start(); } }, {passive:true});
    show(0); start();
  }

  /* ================= Date direction isolation (RTL) ================= */
  function darnaIsolateDates(root) {
    if (!root || !document.createTreeWalker) return;
    var re = /\d{4}-\d{2}-\d{2}/;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    var nodes = [], n;
    while ((n = walker.nextNode())) { if (re.test(n.nodeValue)) nodes.push(n); }
    nodes.forEach(function (node) {
      var parts = node.nodeValue.split(/(\d{4}-\d{2}-\d{2})/);
      var frag = document.createDocumentFragment();
      parts.forEach(function (p) {
        if (/^\d{4}-\d{2}-\d{2}$/.test(p)) {
          var b = document.createElement('bdi');
          b.setAttribute('dir', 'ltr');
          b.textContent = p;
          frag.appendChild(b);
        } else if (p) { frag.appendChild(document.createTextNode(p)); }
      });
      if (node.parentNode) node.parentNode.replaceChild(frag, node);
    });
  }

  /* ================= Preferred properties native strip ================= */
  function darnaInitPreferredSlider() {
    var root = document.querySelector('[data-preferred-carousel="1"]');
    if (!root || root.getAttribute('data-init') === '1') return;
    root.setAttribute('data-init', '1');
    var viewport = root.querySelector('.preferred-viewport');
    var prev = root.querySelector('.preferred-prev'), next = root.querySelector('.preferred-next');
    if (!viewport) return;
    function move(direction) {
      var distance = Math.max(220, Math.round(viewport.clientWidth * .82));
      viewport.scrollBy({ left: direction * distance, behavior: 'smooth' });
    }
    if (prev) prev.addEventListener('click', function () { move(-1); });
    if (next) next.addEventListener('click', function () { move(1); });
  }

  /* ================= Add-property section ================= */
  window.PLACEDJ_ADD_PROPERTY_URL = '';
  window.PLACEDJ_ADD_PROPERTY_URL_IS_PLACEHOLDER = false;
  function darnaInitAddProperty() {
    var btn = document.getElementById('add-property-btn');
    if (!btn) return;
    var url = String(window.PLACEDJ_ADD_PROPERTY_URL || '').trim();
    if (!btn) return;
    if (!url || url === '#') return;
    btn.setAttribute('href', url);
    if (window.PLACEDJ_ADD_PROPERTY_URL_IS_PLACEHOLDER) {
      btn.addEventListener('click', function (e) { e.preventDefault(); var note=document.getElementById('add-property-note'); if (note) note.textContent='رابط النموذج مؤقت وغير مفعل بعد؛ استبدله من إعدادات القالب قبل النشر.'; });
    }
  }

  /* ================= Local visitor rating ================= */
  function darnaInitRating() {
    var root = document.getElementById('property-rating');
    if (!root || root.getAttribute('data-rating-init') === '1') return;
    root.setAttribute('data-rating-init', '1');
    var post = document.querySelector('.property-detail[data-post-id]');
    var id = post ? post.getAttribute('data-post-id') : window.location.pathname;
    var key = 'placedj_ratings_v1';
    var values = {};
    try { values = JSON.parse(localStorage.getItem(key) || '{}') || {}; } catch (e) { values = {}; }
    var status = document.getElementById('rating-status');
    var buttons = Array.prototype.slice.call(root.querySelectorAll('[data-rating]'));
    function paint(value) { buttons.forEach(function (b) { b.classList.toggle('is-selected', Number(b.getAttribute('data-rating')) <= value); }); }
    var current = Number(values[id] || 0); if (current) paint(current);
    buttons.forEach(function (button) { button.addEventListener('click', function () { var value = Number(button.getAttribute('data-rating')); values[id] = value; try { localStorage.setItem(key, JSON.stringify(values)); } catch (e) {} paint(value); if (status) status.textContent = 'تم حفظ تقييمك محليًا لهذا العقار في هذا المتصفح.'; }); });
  }

  /* ================= Init ================= */
  function darnaInit() {
    document.querySelectorAll('.property-card').forEach(function (c) {
      if (c.closest('#similar-grid')) return;
      darnaRenderCard(c);
    });
    document.querySelectorAll('.property-photo-carousel').forEach(function (b) {
      if (b.closest('#similar-grid')) return;
      darnaCarousel(b);
    });
    darnaRenderDetail();
    document.querySelectorAll('.post-body').forEach(function (b) { darnaIsolateDates(b); });
    var waCta = document.querySelector('.whatsapp-cta');
    if (waCta) {
      var ttlEl = document.querySelector('.detail-title');
      var waMsg = 'استفسار عن العقار: ' + (ttlEl ? ttlEl.textContent.trim() : document.title) + '\n' + window.location.href;
      waCta.setAttribute('href', 'https://wa.me/25377313443?text=' + encodeURIComponent(waMsg));
    }
    darnaInitInquiry();
    darnaInitRating();
    darnaInitFavorites();
    darnaInitCompare();
    darnaInitLang();
    darnaInitFilters();
    darnaInitAddProperty();
    darnaInitHeroSlider();
    darnaInitPreferredSlider();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', darnaInit);
  else darnaInit();
})();
